<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/config/config.php'; require_once ROOT_PATH.'/includes/functions.php';
$q=trim((string)($_GET['q']??'')); $products=[]; $error=null; $supplier=(int)($_GET['supplier']??0);
try{$products=(new Product())->wholesaleSearch($q,null,0,60); if($supplier>0)$products=array_values(array_filter($products,static fn($p)=>(int)$p['supplier_id']===$supplier));}catch(PDOException $e){error_log('B2B products: '.$e->getMessage());$error='Products are temporarily unavailable.';}
