lass="b2b-moq">MOQ: <strong><?= (int)$p['minimum_order_quantity']?> <?=e($p['unit']?:'units')?></strong></p><div class="b2b-supplier"><span class="supplier-mini-avatar"><?=e(strtoupper(substr((string)$p['supplier_name'],0,1)))?></span><span><strong><?=e($p['supplier_name'])?></strong><small><?=e(implode(', ',array_filter([$p['city'],$p['country']])))?></small></span></div><a class="button button-primary" href="<?=e(BASE_URL)?>/b2b/request-quotation.php?product=<?= (int)$p['id']?>">Request quote</a></div></article><?php endforeach;?></div><?php endif;?></main></body></html>